#!/bin/bash
# Normalize+strip every set32 board (one pcbnew process each, segfault-safe).
# Reuses prep_set2.py (generic: <src> <routed_dst> <stripped_dst>).
#   stripped, unrouted boards -> boards_unrouted_set32/
#   normalized routed reference + .kicad_pro -> boards_set32/
# Auto-generated by assemble_corpus.py. Sources are modern KiCad (v6+).
set -u
SELF="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
STRESS="${STRESS_DIR:-$HOME/Documents/kicad_stress_test}"
SRC="$STRESS/sources/github_set32"
KPY="${KICAD_PYTHON:-/Applications/KiCad/KiCad.app/Contents/Frameworks/Python.framework/Versions/Current/bin/python3}"
PREP="$SELF/prep_set2.py"
mkdir -p "$STRESS/boards_unrouted_set32" "$STRESS/boards_set32"

# short-name | source-filename-fragment (unique within github_set32/)
MAP=(
  "argos_demo|argos_demo"
  "bitaxe_ultra|bitaxe_ultra"
  "buildbotics_controller|buildbotics_controller"
  "cm4_lvds|cm4_lvds"
  "cvbs_mipi_bridge|cvbs_mipi_bridge"
  "discretesim_hwtest|discretesim_hwtest"
  "dual_ipex_csi_interposer|dual_ipex_csi_interposer"
  "ecp5_bga381_ft2232|ecp5_bga381_ft2232"
  "ecp5_dc_scm|ecp5_dc_scm"
  "emberone|emberone"
  "ender3_loadcell|ender3_loadcell"
  "ftdi_jtag_programmer|ftdi_jtag_programmer"
  "gmsl_serializer_board|gmsl_serializer_board"
  "hackrf_pro|hackrf_pro"
  "kintex_pcie|kintex_pcie"
  "pmod_i3c_sensor|pmod_i3c_sensor"
  "rp2040_devboard|rp2040_devboard"
  "rp2350_pico2_bb48|rp2350_pico2_bb48"
  "seven|seven"
  "si_test_board|si_test_board"
  "stm32h7_hdmi_sodimm|stm32h7_hdmi_sodimm"
  "tiliqua_motherboard|tiliqua_motherboard"
  "trellis_core|trellis_core"
  "water_level_monitor|water_level_monitor"
  "xerxes_cm4_blade|xerxes_cm4_blade"
)

for entry in "${MAP[@]}"; do
  IFS='|' read -r name frag <<< "$entry"
  srcfile=$(find "$SRC" -maxdepth 1 -name '*.kicad_pcb' -name "*${frag}*" | head -1)
  if [ -z "$srcfile" ]; then echo "MISS $name (frag '$frag')"; continue; fi
  echo "== $name <- $(basename "$srcfile")"
  "$KPY" "$PREP" "$srcfile" "$STRESS/boards_set32/$name.kicad_pcb" \
         "$STRESS/boards_unrouted_set32/$name.kicad_pcb" 2>/dev/null || echo "  FAIL $name"
  profile="${srcfile%.kicad_pcb}.kicad_pro"
  [ -f "$profile" ] && cp "$profile" "$STRESS/boards_set32/$name.kicad_pro"
done
echo "Done. stripped -> boards_unrouted_set32/ ; routed reference -> boards_set32/"
